module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire [1:0] in0;
    wire [1:0] in1;

    // Inverter for sel[1] and sel[0] to get complemented signals
    wire not_sel1, not_sel0;
    assign not_sel1 = ~sel[1];
    assign not_sel0 = ~sel[0];

    // Decoder to select one of the four inputs
    assign in0 = {in[1], in[0], in[3], in[2]};  // This line seems to incorrectly map the connections, adjust based on the circuit
    assign in1 = {in[3], in[2], in[1], in[0]};  // This line also seems incorrect; re-evaluate according to the actual logic

    wire local_0, local_1, local_2, local_3;
    assign local_0 = in0 & not_sel1 & not_sel0;
    assign local_1 = in0 & not_sel1 & sel[0];
    assign local_2 = in1 & sel[1] & not_sel0;
    assign local_3 = in1 & sel[1] & sel[0];

    // Generating the output from selected inputs
    wire and_0, and_1, and_2, and_3;
    wire or_0, and_2x, and_3x;
    assign and_0 = local_0;  // Adjust based on actual circuit connections
    assign and_1 = local_1;
    assign and_2 = local_2;
    assign and_3 = local_3;

    assign or_0 = and_0 | and_3;
    assign and_2x = and_2 & not_sel0;
    assign and_3x = and_3 & sel[0];

    wire intermediate_or, final_output, or_1, or_2, or_3;
    assign or_1 = and_1 | and_3x;
    assign or_2 = and_2x | and_3;
    assign or_3 = or_1 | or_2;
    assign intermediate_or = and_0 | or_3;
    assign final_output = intermediate_or;  /* Adjust layers as needed to match the circuit */

    assign out = final_output;

endmodule

module mux4to1 (
