    wire w1, w2, w3, w4;
    wire out1, out2;

    assign s1 = sel;
    assign s0 = {sel[1] ^ sel[0], sel[0]};
    assign in1 = {in[3], in[0]};
    assign in2 = {in[2], in[1]};

    nand2 w1(s0, in0, in2);
    nand2 w2(s0, in1, in3);

    nand2 w3(s1, in1, in3);
    nand2 w4(s1, in0, in2);

    nand2 w5(s0, in3, w4);
    nand2 w6(s0, in2, w1);
    nand2 w7(s1, in3, w2);
    nand2 w8(s1, in2, w3);

    nand2 w9(w5, w6, w7);
    nand2 w10(w5, w6, w8);

    not g1(in1);
    not g2(in2);

    nand2 w11(w10, out2, w10);

    nand2 w12(in2, in1, out1);

    nand2 w13(w12, out2, out1);

    nand2 w14(out1, out2, out);
