module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire [3:0] a_xor_b;
    wire [3:0] a_and_b;
    wire [3:0] a_nand_b;
    wire [3:0] a_nor_b;
    wire [3:0] a_and_not_b;
    wire [3:0] a_nand_not_b;
    wire [3:0] a_and_not_b2;
    wire [3:0] a_nand_not_b2;
    wire [3:0] a_and_not_b3;
    wire [3:0] a_nand_not_b3;
    wire [3:0] a_and_not_b4;
    wire [3:0] a_nand_not_b4;

    // First part of the circuit
    assign a_xor_b = a ^ b;
    assign a_and_b = a & b;
    assign a_nand_b = ~(a & b);
    assign a_nor_b = ~(a | b);
    assign a_and_not_b = a & ~b;
    assign a_nand_not_b = ~(a & ~b);

    // Second part of the circuit
    assign a_and_not_b2 = a & ~b[1];
    assign a_nand_not_b2 = ~(a & ~b[1]);
    assign a_and_not_b3 = a & ~b[2];
    assign a_nand_not_b3 = ~(a & ~b[2]);
    assign a_and_not_b4 = a & ~b[3];
    assign a_nand_not_b4 = ~(a & ~b[3]);

    // Third part of the circuit
    wire [3:0] equal_1;
    wire [3:0] equal_2;

    assign equal_1 = a_nand_not_b & a_nand_not_b2 & a_nand_not_b3 & a_nand_not_b4;
    assign equal_2 = a_and_not_b & a_and_not_b2 & a_and_not_b3 & a_and_not_b4;

    assign equal = (equal_1 & equal_2) | (a_nand_b & a_nand_b2 & a_nand_b3 & a_nand_b4);
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire w1, w2, w3, w4, w5, w6, w7, w8, w9, w10, w11, w12, w13, w14;

    // First comparison stage for each bit
    xnor xnor_0 (w1, a[0], b[0]);
    xnor xnor_1 (w2, a[1], b[1]);
    xnor xnor_2 (w3, a[2], b[2]);
    xnor xnor_3 (w4, a[3], b[3]);

    // AND gate for each bit's comparison result
    and and_0 (w5, w1, w2);
    and and_1 (w6, w3, w4);
    and and_2 (w7, w5, w6);

    // OR gate for final comparison result
    or or_0 (equal, w7, w8, w9);

    // Additional components as per the diagram
    wire w10, w11, w12, w13, w14, w15, w16;
    and and_3 (w10, a[0], a[1]);
    and and_4 (w11, a[2], a[3]);
    and and_5 (w12, b[0], b[1]);
    and and_6 (w13, b[2], b[3]);
    xor xor_0 (w14, w10, w11);
    xor xor_1 (w15, w12, w13);
    and and_7 (w8, w14, w15);
    and and_8 (w9, w12, w13);
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire [3:0] a_eq_b, not_a, not_b, and_out1, and_out2;
    assign not_a = ~a;
    assign not_b = ~b;
    assign a_eq_b[0] = a[0] & b[0];
    assign a_eq_b[1] = a[1] & b[1];
    assign a_eq_b[2] = a[2] & b[2];
    assign a_eq_b[3] = a[3] & b[3];
    assign and_out1 = a_eq_b & (not_a | not_b);
    assign and_out2 = a_eq_b & a;
    assign equal = ~(and_out1 | and_out2);
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire [3:0] a_0, a_1, a_2, a_3;
    wire [3:0] b_0, b_1, b_2, b_3;

    assign a_0 = ~a;
    assign a_1 = a & 1;
    assign a_2 = a & 2;
    assign a_3 = a & 4;

    assign b_0 = ~b;
    assign b_1 = b & 1;
    assign b_2 = b & 2;
    assign b_3 = b & 4;

    wire w1, w2, w3, w4, w5, w6, w7, w8;

    assign w1 = a_0 & b_0 & a_1 & b_1 & a_2 & b_2 & a_3 & b_3;
    assign w2 = a_0 & b_0 & a_1 & b_1 & a_2 & b_2 & ~a_3 & ~b_3;
    assign w3 = a_0 & b_0 & a_1 & b_1 & ~a_2 & ~b_2 & a_3 & b_3;
    assign w4 = ~a_0 & ~b_0 & a_1 & b_1 & a_2 & b_2 & a_3 & b_3;
    assign w7 = a_0 & b_0 & ~a_1 & ~b_1 & a_2 & b_2 & a_3 & b_3;
    assign w8 = a_0 & b_0 & ~a_1 & ~b_1 & ~a_2 & ~b_2 & a_3 & b_3;

    assign equal = w1 | w2 | w3 | w4 | w7 | w8;

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire [3:0] a_nor_b;
    wire [3:0] a_xor_b;
    wire [3:0] a_xor_b_not;
    wire [3:0] a_or_b;
    wire [3:0] a_or_b_not;
    wire [3:0] a_eq_b_1;
    wire [3:0] a_eq_b_2;
    wire [3:0] a_eq_b_3;
    wire [3:0] a_eq_b_4;

    assign a_nor_b = ~(a | b);
    assign a_xor_b = a ^ b;
    assign a_xor_b_not = ~a_xor_b;
    assign a_or_b = a | b;
    assign a_or_b_not = ~(a | b);
    assign a_eq_b_1 = a_nor_b & a_or_b;
    assign a_eq_b_2 = a & b;
    assign a_eq_b_3 = ~a & ~b;
    assign a_eq_b_4 = a_eq_b_1 | a_eq_b_2 | a_eq_b_3 | a_eq_b_4;

    assign equal = ~a_eq_b_4;

endmodule

