module TopModule (
  input clk,
  input w,
  input R,
  input E,
  input L,
  output reg Q
);
  reg D;
  reg S;

  always @ (posedge clk) begin
    S <= w & R & ~L;
    D <= w & ~R & L | ~E & ~S;
  end

  always @ (posedge clk or negedge E or posedge S) begin
    if (E) begin
      if (S) begin
        $display("ERROR: set without holding");
        Q <= 1;
      end else begin
        Q <= D;
      end
    end else if (~E && S) begin
      $display("ERROR: to set but not holding");
      Q <= 1;
    end
  end
endmodule

