);

  reg [3:0] state;
  reg [2:0] count;

  always @(posedge clk) begin
    if (~count_ena) begin
      count <= 3'd0;
    end else begin
      count <= count + 1;
    end

    if (count_ena) begin
      if (~shift_ena) begin
        state <= {state[2:0], data};
      end else begin
        state <= {state[2:0], 1'b1};
      end
      q <= state;
    end
  end
