    3'b001: z = x;
    3'b010: z = ~x;
    3'b011: z = ~x;
    3'b100: z = 1'b1;
    3'b101: z = ~x;
    3'b110: z = x;
    3'b111: z = 1'b1;
  endcase

  case (y)
    3'b000: Y0 = 1'b1;
    3'b001: Y0 = ~clk;
    3'b010: Y0 = y[1] ^ y[2];
    3'b011: Y0 = y[1] | y[2];
    3'b100: Y0 = clk | x;
    3'b101: Y0 = y[1] & y[2];
    3'b110: Y0 = y[1] & y[2] ^ clk;
    3'b111: Y0 = 1'b1;
  endcase
end

endmodule

