reg [4:0] ccounter;
reg [4:0] ccounter_next;
reg [2:0] shift_reg;
reg [2:0] shift_reg_next;
reg valid_out;
reg dout;
reg c, d, R, Q;
reg [4:0] c, d, R, Q;

assign counter = counter_next;

