    if (!rst_n) begin
        shift_reg <= 3'b000;
        ccounter <= 5'b00000;
        counter <= 3'b000;
        valid_out <= 1'b0;
        dout <= 1'b0;
    end else begin
        shift_reg <= shift_reg_next;
        ccounter <= ccounter_next;
        counter <= counter_next;
        valid_out <= valid_out_next;
        dout <= dout_next;
    end
end

always @(*) begin
    counter_next = counter;
    ccounter_next = ccounter;
    shift_reg_next = shift_reg;
    valid_out_next = valid_out;
    dout_next = dout;

    if (counter == 3'b111) begin
        counter_next = 3'b000;
        valid_out_next = 1'b1;
    end else begin
        counter_next = counter + 1'b001;
        valid_out_next = 1'b0;
    end

    if (ccounter == 5'b11111) begin
        ccounter_next = 5'b00000;
        valid_out_next = 1'b1;
    end else begin
        ccounter_next = ccounter + 1'b00001;
        valid_out_next = 1'b0;
    end

    if (shift_reg == 3'b111) begin
        shift_reg_next = 3'b000;
        dout_next = 1'b1;
    end else begin
        shift_reg_next = shift_reg + 1'b001;
        dout_next = 1'b0;
    end
